  2904→function sanitizePaginationArea(selector) {
  2905→    document.querySelectorAll(selector).forEach(root => {
  2906→        function clean() {
  2907→            // Remove icons (svg, i, img) and large injected nodes
  2908→            root.querySelectorAll('svg,i,img').forEach(e => e.remove());
  2909→            root.querySelectorAll('*').forEach(el => {
  2910→                try {
  2911→                    const rect = el.getBoundingClientRect();
  2912→                    const tag = el.tagName || '';
  2913→                    // Hide any element that's clearly oversized inside pagination
  2914→                    if ((rect.width > 48 || rect.height > 48) && !['BUTTON','A','UL','LI','NAV','SPAN'].includes(tag)) {
  2915→                        el.style.display = 'none';
  2916→                    }
  2917→                    // Ensure buttons/links show text, not icons
  2918→                    if ((tag === 'A' || tag === 'BUTTON' || tag === 'SPAN') && el.querySelectorAll && el.querySelectorAll('svg,i,img').length) {
  2919→                        el.querySelectorAll('svg,i,img').forEach(x=>x.remove());
  2920→                        if (!el.textContent.trim()) {
  2921→                            // set sensible fallback
  2922→                            if (el.getAttribute('aria-label') && /previous/i.test(el.getAttribute('aria-label'))) el.textContent = '‹';
  2923→                            else if (el.getAttribute('aria-label') && /next/i.test(el.getAttribute('aria-label'))) el.textContent = '›';
  2924→                        }
  2925→                    }
  2926→                } catch (e) {
  2927→                    // ignore
  2928→                }
  2929→            });
  2930→        }
  2931→        clean();
  2932→        const mo = new MutationObserver(clean);
  2933→        mo.observe(root, { childList: true, subtree: true, attributes: true });
  2934→    });
