    ============================================================ */
    .alert-auto-dismiss {
        position: relative;
        overflow: hidden;
    }
    .alert-auto-dismiss::after {
        content: '';
        position: absolute;
        bottom: 0; left: 0;
        height: 3px;
        background: currentColor;
        opacity: .3;
        animation: alertProgress 5s linear forwards;
    }
    @keyframes alertProgress { from { width: 100%; } to { width: 0%; } }

    /* ============================================================
