        .sidebar, .topbar, .mobile-bottom-nav, #scrollTop,
        #globalToastWrap, #navProgress, .no-print { display: none !important; }
        .main-content { margin: 0 !important; }
        .dashboard-card { box-shadow: none !important; break-inside: avoid; }
